using System.ComponentModel.DataAnnotations;
namespace CrochetCraft.Models;
public class AppUser { public int Id {get;set;} [Required,MaxLength(80)] public string Name {get;set;}=""; [Required,EmailAddress,MaxLength(150)] public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public string Role {get;set;}="Customer"; }
public class Product { public int Id {get;set;} [Required,MaxLength(100)] public string Name {get;set;}=""; [Required,MaxLength(40)] public string Category {get;set;}="Keychain"; [Range(1,100000)] public decimal BasePrice {get;set;}=150; [Range(1,5000)] public decimal YarnGrams {get;set;}=25; public string Description {get;set;}=""; public string Emoji {get;set;}="🧶"; public bool Active {get;set;}=true; }
public class Material { public int Id {get;set;} [Required] public string Name {get;set;}=""; [Range(0,1000000)] public decimal StockGrams {get;set;} [Range(0,100000)] public decimal ReorderLevel {get;set;}=100; }
public class Design { public int Id {get;set;} public int UserId {get;set;} public int ProductId {get;set;} public Product? Product {get;set;} public string Color {get;set;}="Rose"; public string Size {get;set;}="Medium"; public string Pattern {get;set;}="Classic"; [MaxLength(40)] public string PersonalName {get;set;}=""; public bool Bow {get;set;} public bool GiftWrap {get;set;} [Range(1,100)] public int Quantity {get;set;}=1; public decimal UnitPrice {get;set;} public decimal YarnRequiredGrams {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }
public class CraftOrder { public int Id {get;set;} public int UserId {get;set;} public AppUser? User {get;set;} public int DesignId {get;set;} public Design? Design {get;set;} [Required,MaxLength(150)] public string ShippingAddress {get;set;}=""; [Required,RegularExpression(@"^[0-9]{10}$",ErrorMessage="Enter a 10-digit mobile number")] public string Phone {get;set;}=""; public string Status {get;set;}="Pending"; public string PaymentMethod {get;set;}="Cash on Delivery"; public string PaymentStatus {get;set;}="Pending"; public decimal Total {get;set;} public DateTime PlacedAt {get;set;}=DateTime.UtcNow; }
